//! Byte parity for `XPSTConfig.save()`.
//!
//! `tests/fixtures/config_save.json` is generated by
//! `xtask/scripts/capture_config_save.py`, which runs the shipped
//! `XPSTConfig.load()` + `save()` over a grid of profiles. This test holds
//! `xpst_surface::config_save` to it byte for byte, because the file it writes
//! is the file the Python engine reads back: a divergence here is a profile the
//! two engines disagree about, not a cosmetic difference.
//!
//! Regenerate the fixture with:
//!
//! ```text
//! PYTHONPATH=src XPST_PYTHON=<venv>/bin/python \
//!     <venv>/bin/python xtask/scripts/capture_config_save.py
//! ```

use std::collections::BTreeMap;

use xpst_config::yaml::Mapping;
use xpst_config::Value;
use xpst_surface::config_save::{render, save_document, SaveRequest};

const FIXTURE: &str = include_str!("fixtures/config_save.json");

/// The two roots the capture templated. They are different directories on
/// purpose: the shipped loader rebases the credential paths onto the config
/// directory but leaves `video.download_dir`/`monitoring.log_file` under `~`.
const PROFILE: &str = "/parity/profile";
const HOME: &str = "/parity/home";

/// The scenario count. A loop over an emptied array asserts nothing, so the
/// count is pinned here as well as in the capture script.
const EXPECTED_SCENARIOS: usize = 9;
/// One row per `XPST_*` override `_apply_env_vars` reads, minus
/// `XPST_TIKTOK_CLIENT_SECRET`, which has its own scenario.
const EXPECTED_ENV_RULES: usize = 70;

fn fixture() -> serde_json::Value {
    serde_json::from_str(FIXTURE).expect("config_save.json parses")
}

fn env_from(pairs: &BTreeMap<String, String>) -> impl Fn(&str) -> Option<String> + '_ {
    move |name: &str| {
        if name == "HOME" {
            return Some(HOME.to_string());
        }
        pairs.get(name).cloned()
    }
}

fn scenario_env(scenario: &serde_json::Value) -> BTreeMap<String, String> {
    scenario["env"]
        .as_object()
        .map(|map| {
            map.iter()
                .map(|(key, value)| (key.clone(), value.as_str().unwrap_or_default().to_string()))
                .collect()
        })
        .unwrap_or_default()
}

fn seed_document(scenario: &serde_json::Value) -> Option<Value> {
    scenario["seed"]
        .as_str()
        .map(|text| xpst_config::yaml::from_str(text).expect("seed parses"))
}

/// The `messenger_set_rules` handler's own body: `str()` on both sides of the
/// map, then the two fields land on the document `save()` will write.
fn apply_messenger_rules(document: &mut Value, mutation: &serde_json::Value) {
    let rules = mutation["rules"].as_object().cloned().unwrap_or_default();
    let mut coerced = Mapping::new();
    for (key, value) in rules {
        let text = match &value {
            serde_json::Value::String(text) => text.clone(),
            other => other.to_string(),
        };
        coerced.insert(Value::from(key.as_str()), Value::String(text));
    }
    let auto_reply = mutation["auto_reply"].as_bool().unwrap_or(true);
    set(
        document,
        &["accounts", "messenger", "auto_reply"],
        Value::Bool(auto_reply),
    );
    set(
        document,
        &["accounts", "messenger", "reply_rules"],
        Value::Mapping(coerced),
    );
}

/// `disconnect_platform`'s config half: flip `enabled` to false when it is true.
fn apply_disconnect(document: &mut Value, platform: &str) -> bool {
    let path = ["accounts", platform, "enabled"];
    let enabled = get(document, &path).map(xpst_surface::config_view::truthy);
    if enabled == Some(true) {
        set(document, &path, Value::Bool(false));
        return true;
    }
    false
}

fn get<'a>(document: &'a Value, path: &[&str]) -> Option<&'a Value> {
    let mut current = document;
    for segment in path {
        current = current.get(segment)?;
    }
    Some(current)
}

fn set(document: &mut Value, path: &[&str], value: Value) {
    let (last, parents) = path.split_last().expect("non-empty path");
    let mut current = document;
    for segment in parents {
        current = current
            .as_mapping_mut()
            .and_then(|map| map.get_mut(segment))
            .expect("path exists");
    }
    let map = current.as_mapping_mut().expect("mapping");
    let slot = map.get_mut(last).expect("leaf exists");
    *slot = value;
}

fn build(
    scenario: &serde_json::Value,
    store_secret: &dyn Fn(&str, &str, &str) -> bool,
) -> Result<Value, String> {
    let env = scenario_env(scenario);
    let lookup = env_from(&env);
    let request = SaveRequest {
        config_dir: std::path::Path::new(PROFILE),
        home: std::path::Path::new(HOME),
        env: &lookup,
        store_secret,
    };
    let seed = seed_document(scenario);
    let mut document = save_document(seed.as_ref(), &request)?;
    if let Some(mutation) = scenario["mutation"].as_object() {
        match mutation["kind"].as_str() {
            Some("messenger_rules") => {
                apply_messenger_rules(&mut document, &scenario["mutation"]);
            }
            Some("disconnect") => {
                let platform = mutation["platform"].as_str().expect("platform");
                apply_disconnect(&mut document, platform);
            }
            other => panic!("unknown mutation {other:?}"),
        }
    }
    Ok(document)
}

#[test]
fn every_scenario_writes_the_shipped_bytes() {
    let fixture = fixture();
    let scenarios = fixture["scenarios"].as_array().expect("scenarios");
    assert_eq!(
        scenarios.len(),
        EXPECTED_SCENARIOS,
        "the fixture lost rows — re-run the capture script"
    );

    let mut checked = 0;
    for scenario in scenarios {
        let name = scenario["name"].as_str().expect("name");
        let expected = scenario["config_yaml"]
            .as_str()
            .expect("config_yaml")
            .replace("<PROFILE>", PROFILE)
            .replace("<HOME>", HOME);
        let stored = std::cell::RefCell::new(Vec::new());
        let store = |dir: &str, key: &str, value: &str| {
            stored
                .borrow_mut()
                .push((dir.to_string(), key.to_string(), value.to_string()));
            true
        };
        let document = build(scenario, &store).unwrap_or_else(|err| panic!("{name}: {err}"));
        let actual = render(&document);
        assert_eq!(actual, expected, "scenario {name} diverged");
        checked += 1;
    }
    assert_eq!(checked, EXPECTED_SCENARIOS);
}

#[test]
fn the_pristine_document_is_the_captured_defaults() {
    let fixture = fixture();
    let defaults = fixture["defaults"]
        .as_str()
        .expect("defaults")
        .replace("<PROFILE>", PROFILE)
        .replace("<HOME>", HOME);
    let document = xpst_config::save_defaults(PROFILE, HOME).expect("defaults");
    assert_eq!(render(&document), defaults);
}

#[test]
fn every_env_override_moves_exactly_the_captured_field() {
    let fixture = fixture();
    let rules = fixture["env_rules"].as_array().expect("env_rules");
    assert_eq!(
        rules.len(),
        EXPECTED_ENV_RULES,
        "the fixture lost rows — re-run the capture script"
    );

    let mut checked = 0;
    for rule in rules {
        let var = rule["var"].as_str().expect("var");
        let probe = rule["probe"].as_str().expect("probe");
        let mut env = BTreeMap::new();
        env.insert(var.to_string(), probe.to_string());
        let lookup = env_from(&env);
        let request = SaveRequest {
            config_dir: std::path::Path::new(PROFILE),
            home: std::path::Path::new(HOME),
            env: &lookup,
            store_secret: &|_, _, _| true,
        };
        let document = save_document(None, &request).unwrap_or_else(|err| panic!("{var}: {err}"));
        let actual = flatten(&document);

        let expected: BTreeMap<String, serde_json::Value> = rule["changes"]
            .as_array()
            .expect("changes")
            .iter()
            .map(|change| {
                (
                    change["path"].as_str().expect("path").to_string(),
                    change["value"].clone(),
                )
            })
            .collect();
        let baseline = flatten(&xpst_config::save_defaults(PROFILE, HOME).expect("defaults"));
        let moved: BTreeMap<String, serde_json::Value> = actual
            .iter()
            .filter(|(path, value)| baseline.get(*path) != Some(*value))
            .map(|(path, value)| (path.clone(), value.clone()))
            .collect();
        assert_eq!(moved, expected, "{var} moved the wrong fields");
        checked += 1;
    }
    assert_eq!(checked, EXPECTED_ENV_RULES);
}

#[test]
fn the_tiktok_client_secret_moves_into_the_store() {
    let fixture = fixture();
    let secret = &fixture["secret_env"];
    let env: BTreeMap<String, String> = secret["env"]
        .as_object()
        .expect("env")
        .iter()
        .map(|(key, value)| (key.clone(), value.as_str().unwrap_or_default().to_string()))
        .collect();
    let lookup = env_from(&env);
    let calls = std::cell::RefCell::new(Vec::new());
    let store = |dir: &str, key: &str, value: &str| {
        calls
            .borrow_mut()
            .push((dir.to_string(), key.to_string(), value.to_string()));
        true
    };
    let request = SaveRequest {
        config_dir: std::path::Path::new(PROFILE),
        home: std::path::Path::new(HOME),
        env: &lookup,
        store_secret: &store,
    };
    let document = save_document(None, &request).expect("document");
    let expected = secret["config_yaml"]
        .as_str()
        .expect("config_yaml")
        .replace("<PROFILE>", PROFILE)
        .replace("<HOME>", HOME);
    assert_eq!(render(&document), expected);
    assert_eq!(
        calls.borrow().as_slice(),
        &[(
            PROFILE.to_string(),
            "tiktok_client_secret".to_string(),
            secret["stored_secret"]
                .as_str()
                .expect("stored")
                .to_string()
        )]
    );
}

#[test]
fn a_failed_store_write_leaves_the_secret_in_the_file() {
    let env: BTreeMap<String, String> = [(
        "XPST_TIKTOK_CLIENT_SECRET".to_string(),
        "parity-secret".to_string(),
    )]
    .into_iter()
    .collect();
    let lookup = env_from(&env);
    let request = SaveRequest {
        config_dir: std::path::Path::new(PROFILE),
        home: std::path::Path::new(HOME),
        env: &lookup,
        store_secret: &|_, _, _| false,
    };
    let document = save_document(None, &request).expect("document");
    assert_eq!(
        get(&document, &["accounts", "tiktok", "client_secret"]),
        Some(&Value::String("parity-secret".to_string()))
    );
}

#[test]
fn a_non_numeric_override_fails_the_load_with_pythons_sentence() {
    let fixture = fixture();
    let bad = &fixture["bad_env"];
    let env: BTreeMap<String, String> = bad["env"]
        .as_object()
        .expect("env")
        .iter()
        .map(|(key, value)| (key.clone(), value.as_str().unwrap_or_default().to_string()))
        .collect();
    let lookup = env_from(&env);
    let request = SaveRequest {
        config_dir: std::path::Path::new(PROFILE),
        home: std::path::Path::new(HOME),
        env: &lookup,
        store_secret: &|_, _, _| true,
    };
    let error = save_document(None, &request).expect_err("must fail");
    // The capture records `f"{type(exc).__name__}: {exc}"`; the writer returns
    // the sentence, so the type prefix is asserted here rather than dropped.
    assert_eq!(
        format!("ValueError: {error}"),
        bad["error"].as_str().expect("error")
    );
}

#[test]
fn the_credentials_are_rebased_but_the_download_dir_is_not() {
    let document = xpst_config::save_defaults(PROFILE, HOME).expect("defaults");
    assert_eq!(
        get(&document, &["accounts", "youtube", "token_file"]),
        Some(&Value::String(format!(
            "{PROFILE}/credentials/youtube_token.json"
        )))
    );
    assert_eq!(
        get(&document, &["video", "download_dir"]),
        Some(&Value::String(format!("{HOME}/.xpst/downloads")))
    );
}

/// Dotted-path → JSON scalar map, so a diff names the field that moved.
fn flatten(value: &Value) -> BTreeMap<String, serde_json::Value> {
    let mut out = BTreeMap::new();
    walk(value, "", &mut out);
    out
}

fn walk(value: &Value, prefix: &str, out: &mut BTreeMap<String, serde_json::Value>) {
    match value {
        Value::Mapping(map) => {
            for (key, item) in map.iter() {
                let key = key.as_str().unwrap_or_default();
                let path = if prefix.is_empty() {
                    key.to_string()
                } else {
                    format!("{prefix}.{key}")
                };
                walk(item, &path, out);
            }
        }
        other => {
            out.insert(prefix.to_string(), xpst_config::output::to_json(other));
        }
    }
}
